import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
import db from "~/db.server";
import { corsJson, corsOptions, validateShop } from "~/lib/api.server";
import { checkRateLimit } from "~/lib/rate-limit.server";
import { hasFeature } from "~/lib/plans";
import { recommendSize } from "~/lib/ai.server";
import type { RecommendInput } from "~/lib/ai.server";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type GenderInput = "male" | "female" | "unisex";
type BodyTypeInput = "slim" | "average" | "athletic" | "plus";
type BodyTypeCalc = "slim" | "regular" | "athletic" | "plus";

interface RecommendRequestBody {
  shop: string;
  chartId: string;
  height: number;
  weight: number;
  unit: "metric" | "imperial";
  gender: GenderInput;
  bodyType: BodyTypeInput;
}

interface ParsedChartData {
  headers: string[];
  units: { default: string; available: string[] };
  rows: Record<string, string>[];
}

// ---------------------------------------------------------------------------
// Loader — handle OPTIONS preflight only
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return corsOptions();
  }
  return corsJson({ error: "Method not allowed" }, { status: 405 });
};

// ---------------------------------------------------------------------------
// Action — POST /api/recommend
// Body JSON: { shop, chartId, height, weight, unit, gender, bodyType }
// ---------------------------------------------------------------------------

export const action = async ({ request }: ActionFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return corsOptions();
  }

  if (request.method !== "POST") {
    return corsJson({ error: "Method not allowed" }, { status: 405 });
  }

  // Parse body
  let body: Partial<RecommendRequestBody>;
  try {
    body = (await request.json()) as Partial<RecommendRequestBody>;
  } catch {
    return corsJson({ error: "Invalid JSON body" }, { status: 400 });
  }

  const { shop, chartId, height, weight, unit, gender, bodyType } = body;

  // Validate shop
  const shopError = validateShop(shop ?? null);
  if (shopError) return shopError;

  // Rate limit: 30 requests per minute per shop
  const rateLimitError = checkRateLimit(`recommend:${shop as string}`, 30);
  if (rateLimitError) return rateLimitError;

  // Validate chartId
  if (!chartId) {
    return corsJson({ error: "chartId is required" }, { status: 400 });
  }

  // Validate height
  if (typeof height !== "number" || height <= 0) {
    return corsJson({ error: "height must be a positive number" }, { status: 400 });
  }

  // Validate weight
  if (typeof weight !== "number" || weight <= 0) {
    return corsJson({ error: "weight must be a positive number" }, { status: 400 });
  }

  // Validate unit
  if (!unit || !["metric", "imperial"].includes(unit)) {
    return corsJson(
      { error: "unit must be 'metric' or 'imperial'" },
      { status: 400 },
    );
  }

  // Validate gender
  if (!gender || !["male", "female", "unisex"].includes(gender)) {
    return corsJson(
      { error: "gender must be 'male', 'female', or 'unisex'" },
      { status: 400 },
    );
  }

  // Validate bodyType
  if (!bodyType || !["slim", "average", "athletic", "plus"].includes(bodyType)) {
    return corsJson(
      { error: "bodyType must be 'slim', 'average', 'athletic', or 'plus'" },
      { status: 400 },
    );
  }

  // Range validation — reject impossible measurements
  const isMetric = unit === "metric";
  const minHeight = isMetric ? 100 : 40;
  const maxHeight = isMetric ? 250 : 98;
  const minWeight = isMetric ? 30 : 66;
  const maxWeight = isMetric ? 300 : 660;

  if (height < minHeight || height > maxHeight) {
    return corsJson(
      {
        error: `height must be between ${minHeight} and ${maxHeight} ${isMetric ? "cm" : "inches"}`,
      },
      { status: 400 },
    );
  }
  if (weight < minWeight || weight > maxWeight) {
    return corsJson(
      {
        error: `weight must be between ${minWeight} and ${maxWeight} ${isMetric ? "kg" : "lbs"}`,
      },
      { status: 400 },
    );
  }

  try {
    // Check recommender is enabled for this shop
    const recommenderConfig = await db.recommenderConfig.findUnique({
      where: { shop: shop as string },
    });

    if (!recommenderConfig?.enabled) {
      return corsJson(
        { error: "AI recommender is not enabled for this shop" },
        { status: 403 },
      );
    }

    // Check subscription plan has aiRecommender feature
    const subscription = await db.subscription.findUnique({
      where: { shop: shop as string },
    });
    const planId = subscription?.planId ?? "free";

    if (!hasFeature(planId, "aiRecommender")) {
      return corsJson(
        { error: "AI recommender requires a Growth or Pro plan" },
        { status: 403 },
      );
    }

    // Fetch the chart scoped to this shop
    const chart = await db.sizeChart.findFirst({
      where: { id: chartId, shop: shop as string, status: "active" },
    });

    if (!chart) {
      return corsJson({ error: "Chart not found" }, { status: 404 });
    }

    // Parse chart data
    let parsedChart: ParsedChartData;
    try {
      const raw = JSON.parse(chart.data) as unknown;
      if (raw !== null && typeof raw === "object" && !Array.isArray(raw)) {
        const obj = raw as Record<string, unknown>;
        parsedChart = {
          headers: Array.isArray(obj.headers) ? (obj.headers as string[]) : [],
          units:
            obj.units !== null &&
            typeof obj.units === "object" &&
            !Array.isArray(obj.units)
              ? (obj.units as { default: string; available: string[] })
              : { default: "in", available: ["in", "cm"] },
          rows: Array.isArray(obj.rows)
            ? (obj.rows as Record<string, string>[])
            : [],
        };
      } else {
        parsedChart = {
          headers: [],
          units: { default: "in", available: ["in", "cm"] },
          rows: [],
        };
      }
    } catch {
      parsedChart = {
        headers: [],
        units: { default: "in", available: ["in", "cm"] },
        rows: [],
      };
    }

    // Convert inputs to metric (cm / kg) — lib/ai.server always expects metric
    const heightCm: number = isMetric ? height : height * 2.54;
    const weightKg: number = isMetric ? weight : weight / 2.20462;

    // Map "unisex" → "female" (neutral anthropometric default)
    const calcGender: "male" | "female" =
      gender === "male" ? "male" : "female";

    // Map "average" → "regular" to match lib/ai.server body type vocabulary
    const calcBodyType: BodyTypeCalc =
      bodyType === "average" ? "regular" : bodyType;

    const input: RecommendInput = {
      height: heightCm,
      weight: weightKg,
      gender: calcGender,
      bodyType: calcBodyType,
      chartData: {
        headers: parsedChart.headers,
        rows: parsedChart.rows,
      },
    };

    const result = recommendSize(input);

    return corsJson({
      recommendedSize: result.recommendedSize,
      confidence: result.confidence,
      alternatives: result.alternatives,
      // Expose as "measurements" to preserve the existing storefront widget contract
      measurements: result.estimatedMeasurements,
    });
  } catch (error) {
    console.error("[api.recommend]", error);
    return corsJson(
      { error: "Unable to process recommendation. Please try again." },
      { status: 500 },
    );
  }
};

